def gop_khoang(ds):
    kq = []
    for s, e in sorted(ds):
        if kq and s <= kq[-1][1]:
            kq[-1][1] = max(kq[-1][1], e)
        else:
            kq.append([s, e])
    return [tuple(x) for x in kq]

def don_bat_thuong(don):
    tb = don.groupby("kh")["tien"].transform("mean")
    return don.loc[don["tien"] > tb, "ma"].tolist()
